pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C{value: 1 ether}();
    }
    function testFuzz_property(uint256 blockDelta, bytes32 guessHash) public {
        // Restrict blockDelta to a reasonable range to keep the test wide but feasible.
        bound(blockDelta, 1, 100);

        // Fund a fuzzed caller and prank to lock in a guess.
        address actor = address(uint160(blockDelta + 1));
        vm.deal(actor, 2 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guessHash);

        // Move forward by blockDelta blocks. After this, the correct version should be past its recorded block,
        // while the buggy version might still be in the future if blockDelta is small.
        vm.roll(block.number + blockDelta);

        // Attempt to settle. The correct version must succeed, while the buggy version reverts for some delta.
        bool ok;
        vm.prank(actor);
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        // The test checks: For every fuzzed input, the reference implementation succeeds.
        // The buggy version will fail (settle reverts) for some inputs because 
        // block.number never reaches the recorded block (block.number + 2) when blockDelta is small.
        assertTrue(ok);
    }
}

