pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash, uint8 blockAdvance) public {
        // Ensure hash is non-zero to make a correct guess possible
        vm.assume(hash != bytes32(0));
        // Ensure we advance at least one block after lockInGuess
        vm.assume(blockAdvance > 0);

        // Fund the caller and deploy C with 1 ether
        address actor = address(0x1234);
        vm.deal(actor, 10 ether);
        vm.deal(address(c), 1 ether);

        // Lock in the guess
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);

        // Advance blocks so settle() can be called
        vm.roll(block.number + blockAdvance);

        // Check if the guess would be correct based on reference logic
        // We need to simulate what the correct answer would be:
        // The block number stored is the block after lockInGuess (block.number + 1)
        // But since we advanced blocks, we need the blockhash of the stored block
        uint256 storedBlock = block.number + 1 - blockAdvance; // This is the block stored by lockInGuess
        // However, we don't have direct access to the stored block number, so we change approach:
        // We will simply call settle and observe if ETH was transferred.
        // The bug: mutant stores hash=0, so answer (keccak256(blockhash)) never equals 0 unless blockhash is 0.
        // blockhash is never zero for a recent block, so settle never transfers.
        // Reference: if hash equals answer, it transfers 2 ether.
        // So we record balance before and after.
        uint256 balanceBefore = actor.balance;

        vm.prank(actor);
        c.settle();

        uint256 balanceAfter = actor.balance;
        // In reference, if guess was correct, balanceAfter = balanceBefore + 2 ether.
        // In mutant, guess is always zero, so answer (non-zero) never matches, balance unchanged.
        // The property: if the submitted hash matches the computed answer, the actor must receive 2 ether.
        // Since we can't compute answer easily without the stored block, we rely on the fuzzer to find a hash that is correct.
        // The mutant will never pay out, so for any hash that is the correct answer, reference pays, mutant doesn't.
        // We assert: if the guess was correct, balance must increase by 2 ether.
        // How to know if it was correct? We can compute the answer if we know the block number.
        // The block number stored is block.number at lockInGuess + 1 = original block + 1.
        // Since we did vm.roll(block.number + blockAdvance), the current block.number is original + blockAdvance.
        // The stored block is original + 1.
        // We need the blockhash of original + 1.
        // We can compute that because the blockhash of a recent block is available.
        uint256 lockBlock = block.number - blockAdvance + 1;
        bytes32 answer = keccak256(abi.encodePacked(blockhash(lockBlock)));
        if (hash == answer) {
            // The guess was correct, so reference should have paid 2 ether.
            assertTrue(balanceAfter >= balanceBefore + 2 ether);
        } else {
            // If not correct, neither should pay, but we can ignore or assert no change.
            // However, the property we want is: when hash equals answer, payment happens.
            // The mutant breaks because it never pays even when hash==answer.
            // So we only assert when hash==answer, which the fuzzer might find.
            // But to make it a universal property, we need a rule that holds always.
            // Perhaps: balanceAfter <= balanceBefore for mutant, but reference might increase.
            // Better: In reference, if hash==answer, balanceAfter > balanceBefore; in mutant, balanceAfter == balanceBefore.
        }
        // This conditional assertion isn't a single assertTrue. We need a single assertion that is true for reference and false for mutant.
        // Let's redesign: The rule: After settle, if the guess was correct, the actor's balance increases by at least 2 ether.
        // We can express as: !(hash == answer) || (balanceAfter >= balanceBefore + 2 ether)
        // That is always true for reference. For mutant, when hash == answer, balanceAfter == balanceBefore, so the right side is false, making the whole statement false.
        assertTrue(!(hash == answer) || (balanceAfter >= balanceBefore + 2 ether));
    }
}

