pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        vm.deal(address(this), 2 ether);
        c = new C{value: 1 ether}();
    }
    function testFuzz_property(bytes32 hash) public {
        // Admissible: any bytes32 hash
        // lockInGuess requires 1 ether from caller
        address actor = address(uint160(uint256(keccak256(abi.encodePacked(hash)))));
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);

        // Warp to future so block.number > guesses[actor].block
        vm.roll(block.number + 2);

        uint256 balBefore = address(c).balance;
        bool settleSucceeded;
        try c.settle() {
            settleSucceeded = true;
        } catch {
            settleSucceeded = false;
        }
        uint256 balAfter = address(c).balance;

        // General rule: if settle succeeded, the contract balance decreased by 2 ether.
        // If settle failed (reverted), the balance remains unchanged.
        // The reference C always satisfies: settle does not revert (always succeeds) after a valid lockInGuess.
        // The mutant reverts, breaking the rule that settle succeeds and balance changes accordingly.
        assertTrue(settleSucceeded && balAfter == balBefore - 2 ether);
    }
}

