import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C{value: 1 ether}();
    }
    function testFuzz_property(bytes32 guessHash, uint8 blockOffset) public {
        // Keep blockOffset reasonable: after lock block is block.number+1, we need to settle after that.
        vm.assume(blockOffset > 0);
        vm.assume(blockOffset < 255);

        address actor = address(uint160(uint256(keccak256(abi.encodePacked(guessHash, blockOffset)))));
        vm.deal(actor, 1 ether);

        // actor locks a guess
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guessHash);

        // move forward past the locked block
        vm.roll(block.number + blockOffset);

        // actor settles - record if pay succeeded
        bool settled;
        uint256 balBefore = actor.balance;
        vm.prank(actor);
        try c.settle() {
            settled = true;
        } catch {
            settled = false;
        }
        uint256 balAfter = actor.balance;

        if (settled && (balAfter > balBefore)) {
            // If settle transferred Ether, guess must have been correct.
            // The correct contract stores the guess; the buggy one leaves guesses[actor].guess == 0.
            // Therefore, in the correct contract, payout implies guessHash == keccak256(blockhash(c.guesses(actor).block)).
            // We retrieve the locked block from the public guesses mapping getter.
            (uint256 lockedBlock, bytes32 storedGuess) = c.guesses(actor);
            bytes32 blockHash = blockhash(lockedBlock);
            bytes32 expectedAnswer = keccak256(abi.encodePacked(blockHash));
            // The invariant: if payout occurred, storedGuess equals expectedAnswer.
            // Bug: storedGuess is always zero, so this fails whenever expectedAnswer != 0 (or blockhash nonzero).
            assertTrue(storedGuess == expectedAnswer);
        } else {
            // If no payout, the invariant is vacuously true.
            assertTrue(true);
        }
    }
}

