        // settleDelay >= 1 so block.number > lock block.
        vm.assume(blockOffset > 0);
        vm.assume(settleDelay >= 1);

        // Setup: we are the guesser
        address guesser = address(this);
        vm.deal(guesser, 2 ether);

        // Lock a guess
        vm.prank(guesser);
        c.lockInGuess{value: 1 ether}(guessHash);

        // Advance blocks so that settle can be called
        vm.roll(block.number + blockOffset + settleDelay);

        uint256 balanceBefore = guesser.balance;

        // Try to settle
        vm.prank(guesser);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("settle()"));
        // If it reverted, the guess was wrong; property vacuously holds for this input.
        if (!ok) {
            // Revert: no transfer happened, property holds (no incorrect increase).
            // We still need to assert something about c's public surface.
            // The invariant is: if settle did not revert, guesser's balance increased by exactly 2 ether.
            // Since it reverted, the implication is true.
