            // Reference: caller must have received 2 ether.
            // Bug: caller did not receive anything, so balance unchanged.
            // Therefore, balanceAfter must equal balanceBefore + 2 ether in reference.
            uint256 balAfter = caller.balance;
            assertTrue(balAfter == balanceBefore + 2 ether);
        } else {
