        vm.deal(player, 1 ether);
        vm.prank(player);
        c.lockInGuess{value: 1 ether}(guess);
        // Advance to a block where blockhash(lockBlock) is available, e.g., block 256
        uint256 lockBlock = block.number + 1;
        vm.roll(lockBlock + 256);
        vm.prank(player);
        // Call settle and capture whether the guess matched
        bool success;
        try c.settle() { success = true; } catch { success = false; }
        // Verify that a match in the reference (based on blockhash) implies guess == keccak256(abi.encodePacked(blockhash(lockBlock)))
        // The bug always uses zero, so a match would require guess == keccak256(abi.encodePacked(bytes32(0)))
        // If the guess matches the reference, it must not match the bug's constant (unless blockhash is zero, which is impossible for non-zero block)
        if (success) {
            bytes32 expectedAnswer = keccak256(abi.encodePacked(blockhash(lockBlock)));
            assertTrue(guess == expectedAnswer);
        }
    }
}

