import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 guesserPriv, bytes32 guess, uint256 warpBlocks) public {
        // 1. Derive guesser address from private key (fuzzed)
        address guesser = vm.addr(guessPriv);
        vm.assume(guesser != address(0));
        // 2. Fund the guesser and the contract with 1 ether each for lockInGuess
        vm.deal(guesser, 1 ether);
        vm.deal(address(c), 1 ether);
        // 3. Lock in the fuzzed guess
        vm.prank(guesser);
        c.lockInGuess{value: 1 ether}(guess);
        // 4. Warp to a future block so settle() can be called
        uint256 settleBlock = block.number + 1 + warpBlocks;
        vm.roll(settleBlock);
        vm.warp(settleBlock * 12); // typical Ethereum block time
        // 5. Settle and capture balance before and after
        uint256 balanceBefore = address(c).balance;
        vm.prank(guesser);
        c.settle();
        uint256 balanceAfter = address(c).balance;
        // 6. Compute expected answer based on which blockhash the reference uses
        bytes32 expectedAnswer = keccak256(abi.encodePacked(blockhash(block.number - warpBlocks - 1)));
        // 7. Assert: balance decreases by 2 ether iff guess matches the reference answer (the rule for the correct contract).
        // The buggy version computes answer using bytes32(0) and thus will decrement whenever guess matches zero hash,
        // violating this exact relationship.
        assertTrue(
            (guess == expectedAnswer && balanceBefore - balanceAfter == 2 ether) ||
            (guess != expectedAnswer && balanceBefore == balanceAfter)
        );
    }
}

