pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum, bytes32 guessHash, address guesser) public {
        vm.assume(blockNum > 0 && blockNum < type(uint256).max);
        vm.assume(guesser != address(0) && guesser != address(c));

        // Setup: contract needs initial 1 ether from guesser?
        // Actually constructor requires 1 ether, but it's payable by deployer.
        // We need to fund the contract so it can pay out 2 ether on correct guess.
        // The constructor already deposits 1 ether. We'll also fund it with extra to cover payouts.
        vm.deal(address(c), 3 ether);

        // Guesser locks in guess
        vm.deal(guesser, 1 ether);
        vm.prank(guesser);
        c.lockInGuess{value: 1 ether}(guessHash);

        // Advance to block number + 1 (one after lock)
        vm.roll(blockNum + 1);

        // Warp to block number where settle can be called (block.number > guess block)
        vm.roll(blockNum + 2);

        uint256 balBefore = address(c).balance;

        bool settled;
        try c.settle() {
            settled = true;
        } catch {
            settled = false;
        }

        uint256 balAfter = address(c).balance;

        // Reference rule: If settle succeeded (guess matches blockhash(blockNum+1)), balance should decrease by exactly 2 ether.
        // The buggy version uses bytes32(0) hash, so if guessHash matches keccak256(abi.encodePacked(bytes32(0))),
        // it incorrectly pays out, leading to a balance decrease that violates the reference rule.
        bytes32 expectedAnswer = keccak256(abi.encodePacked(blockhash(blockNum + 1)));
        bool shouldWin = (guessHash == expectedAnswer);

        // For the reference: balance decreases by 2 ether iff shouldWin is true.
        // For buggy: it also decreases when guessHash == keccak256(abi.encodePacked(bytes32(0))), which may not match shouldWin.
        if (settled) {
            // If settle succeeded, the balance change must be exactly 2 ether decrease if and only if shouldWin was true.
            uint256 delta = balBefore - balAfter;
            bool referenceRule = (delta == 2 ether) == shouldWin;
            // The bug will break this because it pays out based on zero-hash.
            assertTrue(referenceRule);
        } else {
            // Settle reverted; balance should be unchanged.
            assertTrue(balBefore == balAfter);
        }
    }
}

