pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 guessBlockOffset, bytes32 hash, uint256 fundAmount) public {
        // 1. Bind admissible params: offset 0..255, fundAmount >= 1 ether for locking
        vm.assume(guessBlockOffset <= 255);
        fundAmount = bound(fundAmount, 1 ether, 10 ether);

        // 2. Setup caller with sufficient ether
        address caller = makeAddr("caller");
        vm.deal(caller, fundAmount + 1 ether);

        // Fund contract with 1 ether for constructor
        vm.deal(address(c), 1 ether);

        // Ensure contract has enough balance to pay out (2 ether)
        vm.deal(address(c), 2 ether);

        // Lock in a guess
        vm.prank(caller);
        c.lockInGuess{value: 1 ether}(hash);

        // Advance block number to (lock block + 1 + offset)
        vm.roll(block.number + 1 + guessBlockOffset);

        // 3. Settlement should succeed if block.number > guesses[caller].block
        // The reference allows settle at exactly block.number = guesses[caller].block + 1
        // The mutant requires block.number > guesses[caller].block + 1, i.e. offset >= 1
        // We assert: settle does not revert when block.number > guesses[caller].block (offset >= 0)
        bool ok;
        vm.prank(caller);
        try c.settle() { ok = true; } catch { ok = false; }

        // By the invariants, lock guarantees guesses[caller].block = block.number + 1 at time of lock.
        // After advancing (1 + offset) blocks, block.number = originalBlock + 1 + offset = guesses[caller].block + offset.
        // Condition block.number > guesses[caller].block is offset > 0.
        // Condition block.number > guesses[caller].block + 1 is offset > 1.
        // So reference always succeeds when offset > 0; mutant fails when offset == 1.
        if (guessBlockOffset > 0) {
            assertTrue(ok);
        }
    }
}

