import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address caller, bytes32 hash, uint256 timingOffset) public {
        // timingOffset determines when settle is called relative to the lock block.
        // 0 means block.number == guesses[caller].block, 1 means exactly one block after.
        timingOffset = timingOffset % 3;
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));

        // Fund the caller and lock in a guess
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        c{value: 1 ether}.lockInGuess(hash);

        // Advance block.number to timingOffset blocks after the lock block
        // guesses[caller].block was set to block.number + 1 at lock time, so we need block.number + 1 + timingOffset
        vm.roll(block.number + 1 + timingOffset);

        // Now the stored block is block.number - timingOffset (the block used in settle is the one set in guesses)
        // The reference allows settle when block.number > stored block, i.e., timingOffset >= 1.
        // The mutant requires block.number > stored block + 1, i.e., timingOffset >= 2.

        vm.prank(caller);
        try c.settle() {
            // Reference succeeds for timingOffset >= 1, mutant for timingOffset >= 2.
            // After a successful settle, guesses[caller].block is reset to 0.
        } catch {
            // Revert
        }

        // Read the public mapping getter: c.guesses(caller).block
        (uint256 storedBlock, ) = c.guesses(caller);

        // After settle, regardless of revert, the stored block should be 0 if settle succeeded.
        // If settle reverted, storedBlock remains unchanged (non-zero).
        // For the reference contract, with timingOffset==1, settle succeeds => storedBlock == 0.
        // For the mutant, with timingOffset==1, settle reverts => storedBlock != 0.
        // Therefore, the reference always satisfies: if timingOffset==1 then storedBlock must be 0.
        // The mutant breaks this rule for timingOffset==1.
        if (timingOffset == 1) {
            assertTrue(storedBlock == 0);
        }
    }
}

